"""Lazily split an iterable into lists of at most ``n`` items."""


def batched(iterable, n):
    if n < 1:
        raise ValueError("n must be at least one")

    iterator = iter(iterable)

    def batches():
        while True:
            batch = []
            for _ in range(n):
                try:
                    batch.append(next(iterator))
                except StopIteration:
                    break
            if not batch:
                return
            yield batch

    return batches()

